package com.zerotrust.internalresource.service;
import com.zerotrust.internalresource.dto.*;import com.zerotrust.internalresource.entity.DeviceResourceEntity;import com.zerotrust.internalresource.repository.DeviceResourceRepository;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.List;
@Service public class DeviceResourceService{public static final String RESOURCE_ID="internal-devices";private final DeviceResourceRepository repository;public DeviceResourceService(DeviceResourceRepository repository){this.repository=repository;}public List<DeviceResourceResponse> findAll(){return repository.findAll().stream().map(DeviceResourceResponse::from).toList();}public DeviceResourceResponse findById(Long id){return DeviceResourceResponse.from(entity(id));}public DeviceResourceResponse create(DeviceResourceRequest request){var entity=new DeviceResourceEntity();entity.setResourceId(RESOURCE_ID);apply(entity,request);var now=Instant.now();entity.setLastHeartbeat(now);entity.setCreatedAt(now);entity.setUpdatedAt(now);return DeviceResourceResponse.from(repository.save(entity));}public DeviceResourceResponse update(Long id,DeviceResourceRequest request){var entity=entity(id);apply(entity,request);entity.setUpdatedAt(Instant.now());return DeviceResourceResponse.from(repository.save(entity));}public void delete(Long id){repository.delete(entity(id));}private DeviceResourceEntity entity(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("device resource not found: "+id));}private void apply(DeviceResourceEntity e,DeviceResourceRequest r){e.setDeviceName(r.deviceName());e.setIpAddress(r.ipAddress());e.setDeviceType(r.deviceType());e.setLocation(r.location());e.setDepartment(r.department());e.setSecurityLevel(r.securityLevel());e.setStatus(r.status());}}
